def medir(rutas):
    n, b = 0, 0
    for r in [x for x in rutas.split(";") if x]:
        p = os.path.join(raiz, r)
        if os.path.isfile(p):
            n += 1; b += os.path.getsize(p)
        elif os.path.isdir(p):
            for dp, _, fs in os.walk(p):
                for f in fs:
                    n += 1; b += os.path.getsize(os.path.join(dp, f))
    return n, round(b / 1e6, 2)


